# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TENVİN İŞARETLERİ: İKİ ÜSTÜN (ـً), İKİ ESRE (ـٍ) VE İKİ ÖTRE (ـٌ) (KK.5.2.2)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. İki Üstün (Fethateyn: ـً)</text>\n  <text x="125" y="100" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Harfin üstüne konulan iki</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11.5" fill="#1e3a8a">eğik çizgidir; «-en / -an» okutur.</text>\n  <text x="125" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• بًا (ben) · كِتَابًا (kitâben)</text>\n  <text x="125" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• عِلْمًا (ilmen) · أَبَدًا (ebeden)</text>\n  <text x="125" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Sonunda genellikle destek elifi (ا) bulunur.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. İki Esre (Kesrateyn: ـٍ)</text>\n  <text x="350" y="100" text-anchor="middle" font-size="11.5" fill="#14532d">• Harfin altına konulan iki</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11.5" fill="#14532d">eğik çizgidir; «-in / -ın» okutur.</text>\n  <text x="350" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">• بٍ (bin) · قَلَمٍ (kalemin)</text>\n  <text x="350" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">• يَوْمٍ (yevmin) · لَيْلٍ (leylin)</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">İnce harfleri «-in», kalınları «-ın» okutur.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">3. İki Ötre (Dammeteyn: ـٌ)</text>\n  <text x="575" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">• Harfin üstüne konulan çift</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11.5" fill="#78350f">ötre işaretidir; «-ün / -un» okutur.</text>\n  <text x="575" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">• بٌ (bün) · رَسُولٌ (resûlün)</text>\n  <text x="575" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">• أَحَدٌ (ehadün) · غَفُورٌ (ğafûrun)</text>\n  <text x="575" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Kelimenin yalnız son harfinde yer alır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CEZİM (ـْ), ŞEDDE (ـّ) VE TENVİN (ـً ـٍ ـٌ) BİRLİKTE OKUMA</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Üç İşaretin Temel Sesletim Farkı</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" fill="#831843">• Cezim (ـْ): Harfi harekesiz bırakır; önceki</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11.5" fill="#831843">harfe çarptırarak birleştirir (مِنْ · أَنْ · لَمْ).</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11.5" fill="#831843">• Şedde (ـّ): Harfi iki kez (önce cezimli, sonra</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11.5" fill="#831843">harekeli) kuvvetli okutur (رَبِّ · إِنَّ · كُلَّ).</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11.5" fill="#831843">• Tenvin (ـً ـٍ ـٌ): Kelime sonuna sakin «n»</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">sesi (-en, -in, -ün) ekler (شَيْئًا · رَبٌّ).</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Birlikte Okuma Kelime Örnekleri</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• مُحَمَّدٌ → Mu - ham - me - dün (Şedde + Tenvin)</text>\n  <text x="520" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• جَنَّاتٍ → Cen - nâ - tin (Şedde + Med + Tenvin)</text>\n  <text x="520" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• شَمْسٌ → Şem - sün (Cezim + Tenvin)</text>\n  <text x="520" y="186" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• قَوْلًا → Kav - len (Cezim + İki Üstün)</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">• حَقًّا → Hak - kan (Şedde + İki Üstün)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TENVİNDE DESTEK ELİFİ VE DURAK (VAKIF) KURALLARI</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="180" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">İki Üstünde Destek Elifi İstisnaları</text>\n  <text x="180" y="102" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Normalde iki üstün alan harfin sonuna</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11.5" fill="#4c1d95">okunmayan bir elif (ا) yazılır: عِلْمًا ، بَيْتًا</text>\n  <text x="180" y="150" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Ancak yuvarlak tâ (ةً) ve hemze (ءً)</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11.5" fill="#4c1d95">ile biten kelimelerde elif eklenmez:</text>\n  <text x="180" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">رَحْمَةً (rahmeten) · مَاءً (mâen)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" fill="#4c1d95">• Elif-i maksûre: هُدًى (hüden)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Tahiyyat ve Kısa Surelerde Uygulama</text>\n  <text x="520" y="102" text-anchor="middle" font-size="11.5" fill="#14532d">• «السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللّٰهِ»</text>\n  <text x="520" y="126" text-anchor="middle" font-size="11.5" fill="#14532d">• «أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ» (Cezim + Şedde)</text>\n  <text x="520" y="150" text-anchor="middle" font-size="11.5" fill="#14532d">• «وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ»</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11.5" fill="#14532d">  (مُحَمَّدًا kelimesinde şedde + iki üstün)</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11.5" fill="#14532d">• İhlas Suresi: «قُلْ هُوَ اللّٰهُ أَحَدٌ» · «كُفُوًا أَحَدٌ»</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Doğru telaffuz anlamı korur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
